import csv
import io
import re


_EXPECTED_WIDTH = 9


def _read_rows(text):
    try:
        csv.field_size_limit(max(131072, len(text) + 1))
    except (OverflowError, ValueError):
        pass

    rows = []
    try:
        reader = csv.reader(
            io.StringIO(text, newline=""),
            delimiter=",",
            quotechar='"',
            doublequote=True,
            strict=False,
        )
        for row in reader:
            rows.append([str(value) for value in row])
    except csv.Error:
        return rows
    return rows


def _header_score(row, following=None):
    if not row:
        return -1000000

    score = 40 - 10 * abs(len(row) - _EXPECTED_WIDTH)
    nonempty = 0
    unique = set()

    for value in row:
        value = value.strip()
        if not value:
            score -= 3
            continue

        nonempty += 1
        unique.add(value.lower())

        if re.search(r"[A-Za-z]", value):
            score += 2
        if re.search(r"\d", value):
            score -= 2
        else:
            score += 1
        if re.fullmatch(r"[A-Za-z_][A-Za-z0-9 _./()&%+\-]*", value):
            score += 3
        if len(value) <= 40:
            score += 1
        elif len(value) > 100:
            score -= 3
        if "\n" in value or "\r" in value:
            score -= 1

    score += nonempty
    if len(unique) == nonempty:
        score += 3

    if following:
        checked = 0
        matching = 0
        for next_row in following:
            if not next_row or not any(str(v).strip() for v in next_row):
                continue
            checked += 1
            if len(next_row) == _EXPECTED_WIDTH:
                matching += 1
            if checked >= 5:
                break
        score += matching * 3

        first_data = next(
            (
                r
                for r in following
                if r and any(str(v).strip() for v in r)
            ),
            None,
        )
        if first_data:
            for index in range(min(len(row), len(first_data))):
                header_value = row[index]
                data_value = first_data[index]
                if (
                    re.search(r"[A-Za-z]", header_value)
                    and not re.search(r"\d", header_value)
                    and re.search(r"\d", data_value)
                ):
                    score += 2

    return score


def _find_header_index(rows):
    best_index = None
    best_score = -1000000

    for index, row in enumerate(rows[:200]):
        if not row or not any(str(value).strip() for value in row):
            continue
        score = _header_score(row, rows[index + 1:index + 8])
        if score > best_score:
            best_score = score
            best_index = index

    return best_index, best_score


def _physical_header_fallback(raw_csv):
    best_offset = None
    best_score = -1000000
    offset = 0

    for line in raw_csv.splitlines(True)[:500]:
        candidate_text = line.rstrip("\r\n")
        candidate_rows = _read_rows(candidate_text)
        if len(candidate_rows) == 1:
            score = _header_score(candidate_rows[0])
            if score > best_score:
                best_score = score
                best_offset = offset
        offset += len(line)

    if best_offset is not None and best_score >= 75:
        return _read_rows(raw_csv[best_offset:])
    return None


def _normalize_row(row, width):
    values = [str(value) for value in row]

    if len(values) < width:
        values.extend([""] * (width - len(values)))
    elif len(values) > width:
        values = values[:width - 1] + [",".join(values[width - 1:])]

    return values


def parse_csv(raw_csv: str):
    if not isinstance(raw_csv, str):
        raw_csv = str(raw_csv)

    if not raw_csv:
        return {"columns": [], "rows": []}

    rows = _read_rows(raw_csv)
    header_index, header_score = _find_header_index(rows)

    if header_index is None or header_score < 65:
        fallback_rows = _physical_header_fallback(raw_csv)
        if fallback_rows:
            rows = fallback_rows
            header_index, header_score = _find_header_index(rows)

    if header_index is None:
        return {"columns": [], "rows": []}

    columns = _normalize_row(rows[header_index], _EXPECTED_WIDTH)
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    data_rows = [
        _normalize_row(row, _EXPECTED_WIDTH)
        for row in rows[header_index + 1:]
    ]

    return {"columns": columns, "rows": data_rows}
